  function dayIndex(now = new Date()) {
    const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    return Math.max(0, Math.round((today - EPOCH) / 86400000));
  }

  function todaysCategories(now = new Date()) {
    const triple = SCHEDULE[dayIndex(now) % SCHEDULE.length];
    return triple.map(key => ({ key, ...CATEGORIES[key] }));
  }

  return { CATEGORIES, SCHEDULE, EPOCH, dayIndex, todaysCategories };
